// Zeitungsdruck: Halftone-Punkte auf gedrehtem Raster — Punktgroesse
// folgt der Dunkelheit; Papier/Tinte einfarbig.
vec4 farbe(vec2 uv, vec4 src)
{
    float hell = dot(src.rgb, vec3(0.299, 0.587, 0.114));
    float winkel = 0.7853982; // 45 Grad
    mat2 rot = mat2(cos(winkel), -sin(winkel), sin(winkel), cos(winkel));
    float raster = 90.0; // Punkte je Bildhoehe
    vec2 gitter = rot * (uv * vec2(uResolution.x / uResolution.y, 1.0)) * raster;
    vec2 zelle = fract(gitter) - 0.5;
    float radius = sqrt(clamp(1.0 - hell, 0.0, 1.0)) * 0.62;
    float punkt = smoothstep(radius, radius - 0.12, length(zelle));
    vec3 papier = vec3(0.95, 0.94, 0.90);
    vec3 tinte = vec3(0.08, 0.08, 0.10);
    return vec4(mix(papier, tinte, punkt), 1.0);
}
